let image_paths_str = std::env::var("IMAGE_PATHS").expect("IMAGE_PATHS not set");
let output_path = std::env::var("OUTPUT_PATH").expect("OUTPUT_PATH not set");
let image_paths: Vec<String> = image_paths_str.split(',').map(|s| s.trim().to_string()).collect();
for p in &image_paths {
    if !std::path::Path::new(p).exists() {
        panic!("input image not found: {}", p);
    }
}

let status = std::process::Command::new("topdf")
    .arg("-o")
    .arg(&output_path)
    .args(&image_paths)
    .status()
    .expect("failed to execute topdf");
if !status.success() {
    panic!("topdf command failed");
}
